#include "Json.h"
#include <limits>
namespace private_input::activity {
void require(bool ok,const char* reason){if(!ok)throw JsonError(reason);}
void validateUtf8(std::string_view s){for(size_t i=0;i<s.size();){unsigned c=(unsigned char)s[i++];if(c<128)continue;unsigned n,v,min;if(c>=0xc2&&c<=0xdf){n=1;v=c&31;min=128;}else if(c>=0xe0&&c<=0xef){n=2;v=c&15;min=2048;}else if(c>=0xf0&&c<=0xf4){n=3;v=c&7;min=65536;}else throw JsonError("invalid UTF8");require(n<=s.size()-i,"truncated UTF8");while(n--){unsigned b=(unsigned char)s[i++];require((b&192)==128,"invalid UTF8 continuation");v=(v<<6)|(b&63);}require(v>=min&&v<=0x10ffff&&!(v>=0xd800&&v<=0xdfff),"invalid UTF8 scalar");}}
namespace {
int hex(char c){return c>='0'&&c<='9'?c-'0':c>='a'&&c<='f'?c-'a'+10:c>='A'&&c<='F'?c-'A'+10:-1;}
class Parser {std::string_view s;size_t pos=0,nodes=0,depthLimit,nodeLimit;
 void ws(){while(pos<s.size()&&(s[pos]==' '||s[pos]=='\r'||s[pos]=='\n'||s[pos]=='\t'))++pos;}
 bool take(char c){ws();if(pos<s.size()&&s[pos]==c){++pos;return true;}return false;}
 void expect(char c){require(take(c),"unexpected JSON token");}
 unsigned unit(){require(s.size()-pos>=4,"truncated escape");unsigned n=0;for(int i=0;i<4;i++){int x=hex(s[pos++]);require(x>=0,"invalid unicode escape");n=n*16+x;}return n;}
 static void scalar(std::string&out,unsigned c){if(c<128)out+=char(c);else if(c<2048){out+=char(192|(c>>6));out+=char(128|(c&63));}else if(c<65536){out+=char(224|(c>>12));out+=char(128|((c>>6)&63));out+=char(128|(c&63));}else {out+=char(240|(c>>18));out+=char(128|((c>>12)&63));out+=char(128|((c>>6)&63));out+=char(128|(c&63));}}
 std::string string(){expect('"');std::string out;while(pos<s.size()){unsigned c=(unsigned char)s[pos++];if(c=='"')return out;require(c>=32,"raw JSON control");if(c!='\\'){out+=char(c);continue;}require(pos<s.size(),"truncated escape");switch(s[pos++]){case '"':out+='"';break;case '\\':out+='\\';break;case '/':out+='/';break;case 'b':out+='\b';break;case 'f':out+='\f';break;case 'n':out+='\n';break;case 'r':out+='\r';break;case 't':out+='\t';break;case 'u':{unsigned x=unit();if(x>=0xd800&&x<=0xdbff){require(s.size()-pos>=2&&s[pos]=='\\'&&s[pos+1]=='u',"missing low surrogate");pos+=2;unsigned y=unit();require(y>=0xdc00&&y<=0xdfff,"invalid low surrogate");x=0x10000+((x-0xd800)<<10)+(y-0xdc00);}require(!(x>=0xd800&&x<=0xdfff),"unpaired surrogate");scalar(out,x);break;}default:throw JsonError("unknown JSON escape");}}throw JsonError("unterminated JSON string");}
 Json value(size_t d){require(d<=depthLimit&&++nodes<=nodeLimit,"JSON structural limit");ws();require(pos<s.size(),"truncated JSON");char c=s[pos];if(c=='"')return Json(string());if(c=='{'){++pos;Json out=Json::object();if(take('}'))return out;do{auto k=string();require(k.size()<=256&&!out.has(k),"duplicate or overlong JSON key");expect(':');out[k]=value(d+1);if(take('}'))return out;expect(',');}while(true);}if(c=='['){++pos;Json out=Json::array();if(take(']'))return out;do{out.items.push_back(value(d+1));if(take(']'))return out;expect(',');}while(true);}for(auto literal:{"true","false","null"}){size_t n=std::char_traits<char>::length(literal);if(s.substr(pos,n)==literal){pos+=n;return literal[0]=='n'?Json():Json(literal[0]=='t');}}require(c>='0'&&c<='9',"unsigned integer or JSON value required");uint64_t n=0;size_t start=pos;while(pos<s.size()&&s[pos]>='0'&&s[pos]<='9'){unsigned v=s[pos++]-'0';require(n<=(UINT64_MAX-v)/10,"integer overflow");n=n*10+v;}require(pos-start==1||s[start]!='0',"leading zero");return Json(n);}
 public:Parser(std::string_view x,size_t d,size_t n):s(x),depthLimit(d),nodeLimit(n){}Json parse(){auto j=value(1);ws();require(pos==s.size(),"trailing JSON");return j;}};
std::string quote(std::string_view s){validateUtf8(s);const char*h="0123456789abcdef";std::string out="\"";for(unsigned char c:s){if(c=='"'||c=='\\'){out+='\\';out+=char(c);}else if(c<32){out+="\\u00";out+=h[c>>4];out+=h[c&15];}else out+=char(c);}return out+'"';}
}
Json Json::parse(std::string_view s,size_t bytes,size_t depth,size_t nodes){require(bytes&&bytes<=8388608&&depth&&depth<=32&&nodes&&nodes<=524288&&s.size()<=bytes,"JSON size limit");validateUtf8(s);return Parser(s,depth,nodes).parse();}
std::string Json::dump()const{switch(kind){case Kind::null:return "null";case Kind::boolean:return flag?"true":"false";case Kind::number:return std::to_string(integer);case Kind::string:return quote(text);case Kind::array:{std::string s="[";for(const auto&v:items){if(s.size()>1)s+=',';s+=v.dump();}return s+']';}case Kind::object:{std::string s="{";for(const auto&v:fields){if(s.size()>1)s+=',';s+=quote(v.first)+':'+v.second.dump();}return s+'}';}}throw JsonError("invalid JSON kind");}
}
